function out = U(Tl, Ta, t, S, x)
%heat equation
n = 1:100;
Us = Tl+1e-2*(Ta-Tl)*x/S;
V = (Tl+Ta)/2+sum(2.*(Ta-Tl).*((-1).^n-1).*exp(-
n.^2.*pi^2.*t./S.^2).*cos(n.*pi.*x./S)/(n.*pi).^2);
out = Us+V;

